// swift-tools-version: 6.2
// The xcframework and Sources/OmnigentCoreFFI/omnigent_ffi.swift are generated by
// apps/apple/scripts/build-core.sh from client-core/ and are not checked in.
import PackageDescription

let package = Package(
  name: "OmnigentCoreFFI",
  platforms: [.iOS(.v26), .macOS(.v26)],
  products: [
    .library(name: "OmnigentCoreFFI", targets: ["OmnigentCoreFFI"])
  ],
  targets: [
    .binaryTarget(name: "omnigent_ffiFFI", path: "omnigent_ffiFFI.xcframework"),
    // UniFFI 0.32.2's async foreign-trait runtime (uniffiTraitInterfaceCallAsync*) captures
    // non-Sendable closures in a Task, which Swift 6 rejects and no uniffi.toml option changes.
    // Only this generated module builds in the Swift 5 language mode; its public types are
    // Sendable, so Swift 6 clients still get full checking. Drop this once UniFFI fixes it.
    .target(
      name: "OmnigentCoreFFI",
      dependencies: ["omnigent_ffiFFI"],
      path: "Sources/OmnigentCoreFFI",
      swiftSettings: [.swiftLanguageMode(.v5)]
    ),
    .testTarget(
      name: "OmnigentCoreFFITests",
      dependencies: ["OmnigentCoreFFI"],
      path: "Tests/OmnigentCoreFFITests"
    ),
  ],
  swiftLanguageModes: [.v6]
)
